// Formulate research queries based on video topic
const videoTopic = $input.item.json.video_topic;
const showName = $input.item.json.show_name;
const queryType = $input.item.json.query_type;

let queries = [];

if (queryType === 'comprehensive') {
  // Generate multiple semantic search queries
  queries = [
    `${videoTopic} in ${showName}`,
    `character analysis ${videoTopic} ${showName}`,
    `episode information ${videoTopic} ${showName}`,
    `fan theories about ${videoTopic} in ${showName}`,
    `${videoTopic} relationships and arcs ${showName}`
  ];
} else if (queryType === 'character_focused') {
  queries = [
    `${videoTopic} character ${showName}`,
    `${videoTopic} relationships ${showName}`,
    `${videoTopic} character development ${showName}`
  ];
} else if (queryType === 'episode_focused') {
  queries = [
    `${videoTopic} episode ${showName}`,
    `${videoTopic} plot summary ${showName}`,
    `${videoTopic} episode analysis ${showName}`
  ];
} else {
  // Single query
  queries = [videoTopic];
}

return queries.map(query => ({
  json: {
    query: query,
    video_topic: videoTopic,
    show_name: showName,
    top_k: $input.item.json.top_k
  }
}));

// Extract and process Pinecone results
const response = $input.item.json;
const query = $input.item.json.query;

let results = [];

if (response.matches && response.matches.length > 0) {
  results = response.matches.map(match => ({
    id: match.id,
    score: match.score,
    metadata: match.metadata,
    query: query
  }));
}

return results.map(result => ({ json: result }));

// Organize and rank research results
const allResults = $input.all();

// Group results by type
let organizedData = {
  characters: [],
  episodes: [],
  enriched_analysis: [],
  all_results: []
};

allResults.forEach(item => {
  const result = item.json;

  if (result.metadata) {
    if (result.metadata.type === 'character') {
      organizedData.characters.push(result);
    } else if (result.metadata.type === 'episode') {
      organizedData.episodes.push(result);
    } else if (result.metadata.type === 'enriched_analysis') {
      organizedData.enriched_analysis.push(result);
    }

    organizedData.all_results.push(result);
  }
});

// Sort each category by relevance score
organizedData.characters.sort((a, b) => b.score - a.score);
organizedData.episodes.sort((a, b) => b.score - a.score);
organizedData.enriched_analysis.sort((a, b) => b.score - a.score);
organizedData.all_results.sort((a, b) => b.score - a.score);

// Remove duplicates based on ID
const uniqueResults = {};
organizedData.all_results = organizedData.all_results.filter(result => {
  if (!uniqueResults[result.id]) {
    uniqueResults[result.id] = true;
    return true;
  }
  return false;
});

return { json: organizedData };

// Generate comprehensive research context
const organizedData = $input.item.json;
const videoTopic = $('Extract Query Parameters').item.json.video_topic;
const showName = $('Extract Query Parameters').item.json.show_name;

let researchContext = {
  video_topic: videoTopic,
  show_name: showName,
  research_completed_at: new Date().toISOString(),
  total_results: organizedData.all_results.length,
  character_data: {
    count: organizedData.characters.length,
    top_matches: organizedData.characters.slice(0, 5).map(c => ({
      name: c.metadata.character_name,
      relevance_score: c.score,
      source: c.metadata.source
    }))
  },
  episode_data: {
    count: organizedData.episodes.length,
    top_matches: organizedData.episodes.slice(0, 5).map(e => ({
      title: e.metadata.episode_title,
      episode_number: e.metadata.episode_number,
      relevance_score: e.score,
      source: e.metadata.source
    }))
  },
  enriched_analysis: {
    count: organizedData.enriched_analysis.length,
    analyses: organizedData.enriched_analysis.map(a => ({
      topic: a.metadata.topic,
      enrichment_type: a.metadata.enrichment_type,
      relevance_score: a.score,
      citations: a.metadata.citations || []
    }))
  },
  full_context: organizedData.all_results
};

return { json: researchContext };
